sys_script_client.script:
function onSubmit() {
    if (g_scratchpad.isFormValid) {
        return true;
    }

    var course = g_form.getValue('course');
    var dateVal = g_form.getValue('date');
    var currentId = g_form.getUniqueValue();

    if (!course || !dateVal) {
        return true;
    }

    var ga = new GlideAjax('NowTrainingScript');
    ga.addParam('sysparm_name', 'checkTrainingDate');
    ga.addParam('sysparm_course', course);
    ga.addParam('sysparm_date', dateVal);
    ga.addParam('sysparm_current_id', currentId);

    ga.getXMLAnswer(function(answer) {
        if (answer === 'true') {
            alert('There is already a training of this course scheduled for this date! Please, select another date.');
            g_form.clearValue('date');
        } else {
            g_scratchpad.isFormValid = true;
            g_form.submit(); 
        }
    });

    return false;
}
